import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Gemini 参考图：锁构图不锁风格","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-reference-image.md","filePath":"tools/gemini-reference-image.md","lastUpdated":1787714366000}'),i={name:"tools/gemini-reference-image.md"};function l(n,t,d,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="gemini-参考图-锁构图不锁风格" tabindex="-1">Gemini 参考图：锁构图不锁风格 <a class="header-anchor" href="#gemini-参考图-锁构图不锁风格" aria-label="Permalink to &quot;Gemini 参考图：锁构图不锁风格&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经官方文档逐一核实；涉及工具（Blender、C4D、Photoshop、ControlNet 等）的具体能力请以各自官方文档为准。</li></ul></div><blockquote><p>提问：用参考图控制构图时，图应该给到什么精度，才能既约束住构图、又不把一个不喜欢的风格也一起锁死？</p></blockquote><h2 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h2><p>控制构图而不污染风格的核心原则是：<strong>「锁定几何透视与体积占位，剥离色彩、材质与光影信息」</strong>。</p><p>当参考图包含高饱和度颜色、特定笔触或复杂光影时，模型的潜在空间会强制将这些特征识别为「风格」并一同继承。理想的参考图应当具有<strong>高几何精度、零风格语义</strong>。</p><h2 id="一、最推荐的-3-种中性参考图形态" tabindex="-1">一、最推荐的 3 种中性参考图形态 <a class="header-anchor" href="#一、最推荐的-3-种中性参考图形态" aria-label="Permalink to &quot;一、最推荐的 3 种中性参考图形态&quot;">​</a></h2><h3 id="_1-3d-极简白模-几何占位-3d-whitebox-graybox-——-工业级首选" tabindex="-1">1. 3D 极简白模 / 几何占位（3D Whitebox / Graybox）—— 工业级首选 <a class="header-anchor" href="#_1-3d-极简白模-几何占位-3d-whitebox-graybox-——-工业级首选" aria-label="Permalink to &quot;1. 3D 极简白模 / 几何占位（3D Whitebox / Graybox）—— 工业级首选&quot;">​</a></h3><ul><li><strong>精度要求</strong>：在 3D 软件（如 Blender / C4D）中用无材质的基础立方体、圆柱或低模人偶摆好机位。</li><li><strong>效果</strong>：100% 锁定相机焦距、地平线高度、前后景遮挡关系与主体体积，但因没有贴图和颜色，生成的材质与艺术风格完全由 Prompt 掌控。</li></ul><h3 id="_2-纯净透视线稿-空间网格-clean-wireframe-line-art" tabindex="-1">2. 纯净透视线稿 / 空间网格（Clean Wireframe / Line Art） <a class="header-anchor" href="#_2-纯净透视线稿-空间网格-clean-wireframe-line-art" aria-label="Permalink to &quot;2. 纯净透视线稿 / 空间网格（Clean Wireframe / Line Art）&quot;">​</a></h3><ul><li><strong>精度要求</strong>：仅保留主体轮廓线与地面透视网格，严禁排线阴影、杂线或素描明暗。</li><li><strong>效果</strong>：模型只提取边缘结构（Edge Detection），将画面渲染风格的解释权 100% 留给文本提示词。</li></ul><h3 id="_3-扁平灰度剪影-质心色块-flat-value-silhouette" tabindex="-1">3. 扁平灰度剪影 / 质心色块（Flat Value Silhouette） <a class="header-anchor" href="#_3-扁平灰度剪影-质心色块-flat-value-silhouette" aria-label="Permalink to &quot;3. 扁平灰度剪影 / 质心色块（Flat Value Silhouette）&quot;">​</a></h3><ul><li><strong>精度要求</strong>：用黑、白、中性灰三种纯色块画出主体、前景与背景的面积配比。</li><li><strong>效果</strong>：精准约束视觉重心与画面留白（Negative Space），彻底避免特定色调污染。</li></ul><h2 id="二、参考图精度与污染风险对照表" tabindex="-1">二、参考图精度与污染风险对照表 <a class="header-anchor" href="#二、参考图精度与污染风险对照表" aria-label="Permalink to &quot;二、参考图精度与污染风险对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参考图类型</th><th>构图约束力</th><th>风格污染风险</th><th>适用场景</th><th>处理建议</th></tr></thead><tbody><tr><td>真实拍摄照片 / 成品插画</td><td>强</td><td>极高（必污染）</td><td>既要构图又要原画质感</td><td>严禁直接输入；必须经过预处理</td></tr><tr><td>3D 无材质白模 / 灰模</td><td>极强</td><td>极低（0% 污染）</td><td>商业产品、复杂场景、精确机位</td><td>最稳方案，直接作为 ControlNet / 参考底图</td></tr><tr><td>单色线稿（无明暗）</td><td>强</td><td>极低</td><td>人物姿态、分镜构图</td><td>保证线条闭合干净，去除草稿杂线</td></tr><tr><td>草图涂鸦（Scribble）</td><td>弱</td><td>低</td><td>概念发散阶段</td><td>容易产生结构漂移，需提高生图步数</td></tr></tbody></table><h2 id="三、手头只有带风格的参考图时-快速「去风格化」的-3-步处理法" tabindex="-1">三、手头只有带风格的参考图时，快速「去风格化」的 3 步处理法 <a class="header-anchor" href="#三、手头只有带风格的参考图时-快速「去风格化」的-3-步处理法" aria-label="Permalink to &quot;三、手头只有带风格的参考图时，快速「去风格化」的 3 步处理法&quot;">​</a></h2><p>若只能使用现成图片做参考，不要直接喂给模型，先做轻量预处理：</p><ol><li><strong>提取结构通道</strong>：使用 Photoshop 或在线工具将图片转为 Canny 边缘线图或 Depth 深度灰度图，只把线图 / 深度图作为参考输入。</li><li><strong>压平色彩与明暗</strong>：若必须使用图生图（I2I），先将原图完全去色（Desaturate 转为黑白），并用大画笔将主体内部的复杂纹理涂成单一中性灰。</li><li><strong>提示词强权覆盖（Prompt Overpowering）</strong>：在 Prompt 中明确写出与原参考图完全相悖的风格词组（如原图是暖色手绘，Prompt 强写 <code>ultra-realistic commercial studio lighting, cold blue tone, 8k photo, clean glossy texture</code>），用高权重文本拉开与参考图风格的差距。</li></ol><hr><p>关联：本文是 <a href="/tools/gemini-shot-consistency">跨镜头一致性</a> 第二步「单镜头定制关键帧」的参考图规范——那篇说「资产参考图 + 构图景别光影」，本篇回答那张参考图该做成白模 / 线稿 / 剪影才不污染风格。</p>',20)])])}const g=e(i,[["render",l]]);export{u as __pageData,g as default};
